if (GC.TryStartNoGCRegion(10_000_000)) // 10 MB budget
{
    try
    {
        // This block runs without any GC pauses.
        // All allocations must stay within the 10 MB budget.
        for (int i = 0; i < batchSize; i++)
        {
            ProcessItem(items[i]);
        }
    }
    finally
    {
        GC.EndNoGCRegion();
    }
}
else
{
    // Not enough memory available for NoGCRegion
    // Fall back to normal GC mode
    ProcessItemsNormally();
}
